"""A case outside the library: found by entry point or decorator, generated by workers,
recorded in the manifest, scaffolded by `new-case` and checked by `check`."""

from __future__ import annotations

import json
import subprocess
import sys
from importlib.metadata import EntryPoint

import numpy as np
import pytest

import plantbench as pb
from plantbench import cases, contract, datagen, report
from plantbench.__main__ import main
from plantbench.core.casekit import StateLayout, fixed_point_residual, state_measurement
from plantbench.scaffold import new_case

# A module defining a case as the template's tank under another id.
TANK_MODULE = """\
import dataclasses

import plantbench as pb
from plantbench.cases._template.definition import CASE as _TANK


def make_design(config):
    return _TANK.make_design(config)


CASE = dataclasses.replace(_TANK, id="{id}", make_design=make_design)


@pb.case("{id}_decorated")
def decorated():
    return dataclasses.replace(CASE, id="{id}_decorated")
"""


@pytest.fixture
def session():
    """Leaves the session registry as it found it."""
    before = dict(cases._SESSION)
    yield
    cases._SESSION.clear()
    cases._SESSION.update(before)


@pytest.fixture
def tank_module(tmp_path, monkeypatch, session):
    """An importable module `ext_tank` holding `CASE` (id `ext_tank`) and a decorated
    case `ext_tank_decorated`."""
    (tmp_path / "ext_tank.py").write_text(TANK_MODULE.format(id="ext_tank"))
    monkeypatch.syspath_prepend(str(tmp_path))
    monkeypatch.delitem(sys.modules, "ext_tank", raising=False)
    import ext_tank
    return ext_tank


def _entry_points(*pairs):
    eps = [EntryPoint(name=n, value=v, group=cases.ENTRY_POINT_GROUP) for n, v in pairs]
    return lambda group: [ep for ep in eps if ep.group == group]


# ------------------------------------------------------------------------------------
# Discovery
# ------------------------------------------------------------------------------------


def test_an_entry_point_is_found_by_its_id(tank_module, monkeypatch):
    monkeypatch.setattr(cases, "entry_points", _entry_points(("ext_tank", "ext_tank:CASE")))
    assert "ext_tank" in pb.list_cases()
    assert pb.load_case("ext_tank") is tank_module.CASE
    assert cases.source("ext_tank") == {"kind": "entry point", "module": "ext_tank"}


def test_an_entry_point_must_give_a_case_of_its_id(tank_module, monkeypatch):
    monkeypatch.setattr(cases, "entry_points", _entry_points(("other_tank", "ext_tank:CASE")))
    with pytest.raises(ValueError, match="its id is 'ext_tank'"):
        pb.load_case("other_tank")


def test_a_package_cannot_declare_a_built_in_id(tank_module, monkeypatch):
    monkeypatch.setattr(cases, "entry_points", _entry_points(("jacketed_cstr", "ext_tank:CASE")))
    with pytest.raises(ValueError, match="a built-in case"):
        pb.list_cases()


def test_register_records_the_module_that_calls_it(session):
    import dataclasses

    from plantbench.cases.jacketed_cstr.definition import CASE
    pb.register(dataclasses.replace(CASE, id="registered_cstr"))
    assert cases.source("registered_cstr")["module"] == __name__


def test_two_packages_cannot_declare_one_id(tank_module, monkeypatch):
    monkeypatch.setattr(cases, "entry_points", _entry_points(
        ("ext_tank", "ext_tank:CASE"), ("ext_tank", "elsewhere:CASE")))
    with pytest.raises(ValueError, match="declared by two packages"):
        pb.list_cases()


def test_the_decorator_builds_the_case_on_first_use(session):
    calls = []

    @pb.case("lazy_tank")
    def lazy_tank():
        import dataclasses

        from plantbench.cases._template.definition import CASE
        calls.append(1)
        return dataclasses.replace(CASE, id="lazy_tank")

    assert calls == [] and "lazy_tank" in pb.list_cases()
    assert pb.load_case("lazy_tank") is pb.load_case("lazy_tank")
    assert calls == [1]
    assert cases.source("lazy_tank") == {"kind": "session", "module": __name__}


def test_the_decorator_refuses_a_case_of_another_id(session):
    @pb.case("named_tank")
    def named_tank():
        from plantbench.cases._template.definition import CASE
        return CASE

    with pytest.raises(ValueError, match="its id is 'template'"):
        pb.load_case("named_tank")


@pytest.mark.parametrize("case_id", ["Tank", "case_tank", "case", "my__tank", "2tank",
                                     "my-tank", "t" * 41])
def test_an_id_outside_the_convention_is_refused(session, case_id):
    with pytest.raises(ValueError, match="is not a case id"):
        pb.case(case_id)


def test_a_built_in_or_installed_id_cannot_be_claimed(tank_module, monkeypatch):
    with pytest.raises(ValueError, match="built-in"):
        pb.case("jacketed_cstr")
    monkeypatch.setattr(cases, "entry_points", _entry_points(("ext_tank", "ext_tank:CASE")))
    with pytest.raises(ValueError, match="already declared"):
        pb.register(tank_module.CASE)


def test_an_installed_package_is_found_by_every_process(tmp_path):
    """The entry point as an installed package leaves it, in a dist-info directory, seen
    by a new interpreter and by the command line."""
    site = tmp_path / "site"
    (site / "ext_tank_pkg-0.1.0.dist-info").mkdir(parents=True)
    (site / "ext_tank.py").write_text(TANK_MODULE.format(id="ext_tank"))
    (site / "ext_tank_pkg-0.1.0.dist-info" / "METADATA").write_text(
        "Metadata-Version: 2.1\nName: ext-tank-pkg\nVersion: 0.1.0\n")
    (site / "ext_tank_pkg-0.1.0.dist-info" / "entry_points.txt").write_text(
        "[plantbench.cases]\next_tank = ext_tank:CASE\n")
    out = subprocess.run([sys.executable, "-m", "plantbench", "list"], capture_output=True,
                         text=True, check=True,
                         env={"PYTHONPATH": str(site), "PATH": "/usr/bin:/bin"})
    assert "ext_tank" in out.stdout and "entry point (ext-tank-pkg)" in out.stdout


