def test_workers_can_run_a_decorated_case(tank_module, tmp_path):
    """Spawned workers import the module that defined the case again."""
    configs = [{"structure": "level PI", "tuning": {"level": {"Kc": k, "tau_I": 10.0}}}
               for k in (-0.2, -0.5)]
    records = datagen.run_configurations("ext_tank_decorated", configs, tmp_path / "d",
                                         {"t_end": 10.0, "dt": 5.0}, workers=2,
                                         log=lambda m: None)
    assert [r["status"] for r in records] == ["ok", "ok"]
    manifest = json.loads((tmp_path / "d" / "manifest.json").read_text())
    assert manifest["case_source"]["kind"] == "session"
    assert manifest["case_source"]["module"] == "ext_tank"


def test_a_built_in_case_records_no_case_source(tmp_path):
    datagen.run_configurations("jacketed_cstr", [{"structure": "temperature PI"}],
                               tmp_path / "d", {"t_end": 10.0, "dt": 5.0}, log=lambda m: None)
    assert "case_source" not in json.loads((tmp_path / "d" / "manifest.json").read_text())


def test_an_interactive_case_is_refused_before_workers_start(session, monkeypatch):
    import dataclasses

    from plantbench.cases._template.definition import CASE
    pb.register(dataclasses.replace(CASE, id="typed_tank"))
    cases._SESSION["typed_tank"].module = "__main__"
    monkeypatch.delattr(sys.modules["__main__"], "__file__", raising=False)
    with pytest.raises(RuntimeError, match="interactive session"):
        datagen._check_workers_can_load("typed_tank")


# ------------------------------------------------------------------------------------
# new-case and check
# ------------------------------------------------------------------------------------


def _import_scaffold(root, case_id, monkeypatch):
    monkeypatch.syspath_prepend(str(root))
    for name in [m for m in sys.modules if m == case_id or m.startswith(case_id + ".")]:
        monkeypatch.delitem(sys.modules, name)
    import importlib
    return importlib.import_module(f"{case_id}.definition").CASE


def test_a_new_case_keeps_the_contract_as_written(tmp_path, monkeypatch):
    root = new_case("new_tank", tmp_path / "new_tank")
    assert {p.relative_to(root).as_posix() for p in root.rglob("*") if p.is_file()} == {
        "pyproject.toml", "new_tank/__init__.py", "new_tank/definition.py",
        "new_tank/model.py", "new_tank/README.md", "tests/test_contract.py"}
    assert 'new_tank = "new_tank.definition:CASE"' in (root / "pyproject.toml").read_text()
    case = _import_scaffold(root, "new_tank", monkeypatch)
    assert case.id == "new_tank"
    assert all(r.passed for r in contract.check(case)), contract.check(case)
    rules = {r.check: r.passed for r in contract.library_rules(case)}
    # The case card and the imports are in order; the case's own tests are still owed.
    assert rules == {"imports_only_what_a_case_may": True, "has_a_case_card": True,
                     "has_tests_of_its_own": False}


def test_the_scaffolded_contract_test_runs_under_pytest(tmp_path):
    root = new_case("pytest_tank", tmp_path / "pytest_tank")
    out = subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider",
                          str(root / "tests")], capture_output=True, text=True,
                         cwd=root, env={"PYTHONPATH": str(root), "PATH": "/usr/bin:/bin"})
    assert out.returncode == 0, out.stdout + out.stderr
    assert f"{len(contract.CHECKS)} passed" in out.stdout


def test_new_case_refuses_a_taken_id_or_a_used_directory(tmp_path):
    with pytest.raises(ValueError, match="already a case"):
        new_case("jacketed_cstr", tmp_path / "a")
    (tmp_path / "b").mkdir()
    (tmp_path / "b" / "x").write_text("")
    with pytest.raises(FileExistsError):
        new_case("b_tank", tmp_path / "b")


def test_a_case_importing_another_case_breaks_the_library_rules(tmp_path, monkeypatch):
    root = new_case("bad_tank", tmp_path / "bad_tank")
    case = _import_scaffold(root, "bad_tank", monkeypatch)
    # The rule reads the source, so the imports are added after the module has loaded.
    definition = root / "bad_tank" / "definition.py"
    definition.write_text("from plantbench.cases.jacketed_cstr.model import LAYOUT\n"
                          "import sklearn\n" + definition.read_text())
    with pytest.raises(contract.ContractError) as info:
        contract.imports_only_what_a_case_may(case)
    assert "imports plantbench.cases.jacketed_cstr.model" in str(info.value)
    assert "imports sklearn, which no extra" in str(info.value)


def test_check_reports_on_the_command_line(capsys):
    assert main(["check", "jacketed_cstr", "--contribute"]) == 0
    out = capsys.readouterr().out
    assert f"{len(contract.CHECKS) + len(contract.RULES)} passed, 0 failed" in out
    assert "open-loop |rhs| at the design point" in out


