# The kit
# ------------------------------------------------------------------------------------


def test_a_state_layout_round_trips_and_names_every_state():
    layout = StateLayout([("M_D", ()), ("x_D", 2), ("x", (3, 2))])
    assert layout.size == 9
    x = np.arange(9.0)
    blocks = layout.unpack(x)
    assert blocks["M_D"] == 0.0 and blocks["x"].shape == (3, 2)
    assert np.array_equal(layout.pack(**blocks), x)
    assert layout.names()[:4] == ["M_D", "x_D[0]", "x_D[1]", "x[0,0]"]
    assert layout.names({"x": ["A", "B"]})[-1] == "x[2,B]"
    assert layout.index("x[1,0]") == 5
    assert state_measurement("x[1,0]", layout)(x, None, None) == 5.0
    with pytest.raises(KeyError):
        layout.pack(M_D=0.0)


def test_the_residual_names_the_states_off_steady_state():
    design = pb.build("jacketed_cstr").design
    worst, where = fixed_point_residual(design, ["C_A", "T", "Tj"])
    assert worst < 1e-9 and {name for name, _ in where} == {"C_A", "T", "Tj"}
    moved = type(design)(pp=design.pp, x=design.x + np.array([0.0, 1.0, 0.0]), u=design.u,
                         branch=design.branch)
    r = moved.rhs(0.0, moved.x, moved.u, moved.pp)
    i = int(np.argmax(np.abs(r)))
    assert fixed_point_residual(moved, ["C_A", "T", "Tj"]) == (
        abs(r[i]), [(n, float(r[k])) for k, n in sorted(enumerate(["C_A", "T", "Tj"]),
                                                         key=lambda kn: -abs(r[kn[0]]))])


def test_the_kit_leaves_jacketed_cstr_as_it_was():
    case = pb.load_case("jacketed_cstr")
    d = pb.build(case).design
    assert case.state_names(d) == ["C_A", "T", "Tj"]
    assert list(case.measurements(d)) == ["C_A", "T", "Tj"]
    assert [f(d.x, d.u, d.pp) for f in case.measurements(d).values()] == list(d.x)
